//! KP20 `S0` strip least-squares projection.
//!
//! KP20 §4.4 defines the strip optimisation as
//! `min ||S - S_target||^2` subject to the linear propagation
//! `S = M * S0 + s_const`. This module owns that projection without
//! assuming the final strip-index layout. The full assembler supplies
//! the rows generated by equations (11)-(13); this solver computes the
//! optimal free `S0` points and reconstructed strip samples.

use super::direct_linalg::{condition_number_dense, solve_dense};
use super::kp20_bi6_cap::{Kp20Bi6Patch, kp20_apply_g2_strip};
use super::kp20_bi6_math::kp20_g2_strip_weights;
use crate::geometry::Point3;

/// One row of the linear strip map `S = M * S0 + s_const`.
#[derive(Debug, Clone, PartialEq)]
pub struct Kp20S0Sample {
    /// Sparse coefficients into the free `S0` point vector.
    pub coeffs: Vec<(usize, f64)>,
    /// Constant contribution independent of `S0`.
    pub constant: Point3,
    /// Target point from guide-Hermite sampling.
    pub target: Point3,
}

impl Kp20S0Sample {
    /// Construct one strip sample equation.
    pub fn new(coeffs: Vec<(usize, f64)>, constant: Point3, target: Point3) -> Self {
        Self {
            coeffs,
            constant,
            target,
        }
    }
}

/// Result of the KP20 `S0` projection.
#[derive(Debug, Clone, PartialEq)]
pub struct Kp20S0Projection {
    /// Least-squares optimal free points.
    pub free_points: Vec<Point3>,
    /// Reconstructed samples `M * S0 + s_const`.
    pub projected_samples: Vec<Point3>,
    /// Squared residual `Σ ||projected - target||²`.
    pub residual_squared: f64,
    /// Condition number of the normal matrix used by the projection.
    pub normal_condition_number: f64,
}

/// Error from the KP20 `S0` projection.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Kp20S0SolveError {
    /// There must be at least one free point.
    EmptyFreeSet,
    /// A sample referenced a free-point index outside `0..num_free`.
    FreeIndexOutOfRange {
        /// Index of the sample containing the bad reference.
        sample: usize,
        /// Referenced free-point index.
        index: usize,
        /// Number of free points supplied to the solve.
        num_free: usize,
    },
    /// Normal-equation matrix was singular for the given coordinate.
    SingularOnAxis(usize),
}

impl std::fmt::Display for Kp20S0SolveError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::EmptyFreeSet => write!(f, "KP20 S0 solve needs at least one free point"),
            Self::FreeIndexOutOfRange {
                sample,
                index,
                num_free,
            } => write!(
                f,
                "KP20 S0 sample {sample} references free index {index}, but num_free is {num_free}"
            ),
            Self::SingularOnAxis(axis) => {
                write!(f, "KP20 S0 normal-equation system singular on axis {axis}")
            }
        }
    }
}

impl std::error::Error for Kp20S0SolveError {}

/// Solve the KP20 `S0` least-squares projection.
pub fn solve_kp20_s0_projection(
    num_free: usize,
    samples: &[Kp20S0Sample],
) -> Result<Kp20S0Projection, Kp20S0SolveError> {
    if num_free == 0 {
        return Err(Kp20S0SolveError::EmptyFreeSet);
    }
    validate_samples(num_free, samples)?;

    let normal = build_normal_matrix(num_free, samples);
    let normal_condition_number = condition_number_dense(&normal)
        .map(|report| report.condition_number)
        .unwrap_or(f64::INFINITY);
    let mut axis_solutions = [
        vec![0.0_f64; num_free],
        vec![0.0_f64; num_free],
        vec![0.0_f64; num_free],
    ];

    for (axis, axis_solution) in axis_solutions.iter_mut().enumerate() {
        let rhs = build_rhs(num_free, samples, axis);
        let solution =
            solve_dense(normal.clone(), rhs).ok_or(Kp20S0SolveError::SingularOnAxis(axis))?;
        *axis_solution = solution;
    }

    let free_points = (0..num_free)
        .map(|i| {
            Point3::new(
                axis_solutions[0][i],
                axis_solutions[1][i],
                axis_solutions[2][i],
            )
        })
        .collect::<Vec<_>>();
    let projected_samples = samples
        .iter()
        .map(|sample| evaluate_sample(sample, &free_points))
        .collect::<Vec<_>>();
    let residual_squared = projected_samples
        .iter()
        .zip(samples)
        .map(|(projected, sample)| {
            let dx = projected.x - sample.target.x;
            let dy = projected.y - sample.target.y;
            let dz = projected.z - sample.target.z;
            dx * dx + dy * dy + dz * dz
        })
        .sum();

    Ok(Kp20S0Projection {
        free_points,
        projected_samples,
        residual_squared,
        normal_condition_number,
    })
}

/// Project one KP20 sector-separating G2 strip pair onto equations
/// (13), using the current patch values as guide-sampled targets.
///
/// Free `S0` layout:
/// - 0: `p_42`
/// - 1: `p_52`
/// - 2: `p_62`
/// - 3: paired `q_42`
/// - 4: paired `q_52`
/// - 5: paired `q_62`
///
/// The projection preserves the current guide-sampled row-2 values as
/// targets while fitting the row-1 G2 strip constraints. On success it
/// writes the optimal row-2 values and then reapplies KP20 equation
/// (13) to derive row 1.
pub fn project_kp20_g2_strip_pair(
    p: &mut Kp20Bi6Patch,
    q: &mut Kp20Bi6Patch,
    b0: f64,
) -> Result<Kp20S0Projection, Kp20S0SolveError> {
    let samples = build_kp20_g2_strip_samples(p, q, b0);
    let projection = solve_kp20_s0_projection(6, &samples)?;
    p.cps[4][2] = projection.free_points[0];
    p.cps[5][2] = projection.free_points[1];
    p.cps[6][2] = projection.free_points[2];
    q.cps[4][2] = projection.free_points[3];
    q.cps[5][2] = projection.free_points[4];
    q.cps[6][2] = projection.free_points[5];
    kp20_apply_g2_strip(p, q, b0);
    Ok(projection)
}

/// Build the linear samples for [`project_kp20_g2_strip_pair`].
pub fn build_kp20_g2_strip_samples(
    p: &Kp20Bi6Patch,
    q: &Kp20Bi6Patch,
    b0: f64,
) -> Vec<Kp20S0Sample> {
    let (w1, w2, w3) = kp20_g2_strip_weights(b0);
    let mut samples = Vec::with_capacity(12);

    for (free_idx, point) in [
        (0, p.cps[4][2]),
        (1, p.cps[5][2]),
        (2, p.cps[6][2]),
        (3, q.cps[4][2]),
        (4, q.cps[5][2]),
        (5, q.cps[6][2]),
    ] {
        samples.push(Kp20S0Sample::new(
            vec![(free_idx, 1.0)],
            Point3::new(0.0, 0.0, 0.0),
            point,
        ));
    }

    for (p_idx, q_idx, i) in [(1, 4, 5), (2, 5, 6)] {
        samples.push(Kp20S0Sample::new(
            vec![(p_idx, 0.25), (q_idx, -0.25)],
            p.cps[i][0],
            p.cps[i][1],
        ));
        samples.push(Kp20S0Sample::new(
            vec![(p_idx, -0.25), (q_idx, 0.25)],
            p.cps[i][0],
            q.cps[i][1],
        ));
    }

    let correction_const = point_sum(&[(-w3, p.cps[5][0]), (w3, p.cps[6][0])]);
    let p41_const = point_sum(&[(1.0, p.cps[4][0]), (1.0, correction_const)]);
    samples.push(Kp20S0Sample::new(
        vec![(0, 0.25), (3, -0.25), (1, w2), (4, -w2), (2, w1), (5, -w1)],
        p41_const,
        p.cps[4][1],
    ));
    samples.push(Kp20S0Sample::new(
        vec![(0, -0.25), (3, 0.25), (1, -w2), (4, w2), (2, -w1), (5, w1)],
        p41_const,
        q.cps[4][1],
    ));
    samples
}

fn validate_samples(num_free: usize, samples: &[Kp20S0Sample]) -> Result<(), Kp20S0SolveError> {
    for (sample_idx, sample) in samples.iter().enumerate() {
        for &(index, _) in &sample.coeffs {
            if index >= num_free {
                return Err(Kp20S0SolveError::FreeIndexOutOfRange {
                    sample: sample_idx,
                    index,
                    num_free,
                });
            }
        }
    }
    Ok(())
}

fn build_normal_matrix(num_free: usize, samples: &[Kp20S0Sample]) -> Vec<Vec<f64>> {
    let mut normal = vec![vec![0.0_f64; num_free]; num_free];
    for sample in samples {
        for &(i, wi) in &sample.coeffs {
            for &(j, wj) in &sample.coeffs {
                normal[i][j] += wi * wj;
            }
        }
    }
    normal
}

fn build_rhs(num_free: usize, samples: &[Kp20S0Sample], axis: usize) -> Vec<f64> {
    let mut rhs = vec![0.0_f64; num_free];
    for sample in samples {
        let target_minus_const = coord(sample.target, axis) - coord(sample.constant, axis);
        for &(i, w) in &sample.coeffs {
            rhs[i] += w * target_minus_const;
        }
    }
    rhs
}

fn evaluate_sample(sample: &Kp20S0Sample, free_points: &[Point3]) -> Point3 {
    let mut out = sample.constant;
    for &(idx, w) in &sample.coeffs {
        out.x += w * free_points[idx].x;
        out.y += w * free_points[idx].y;
        out.z += w * free_points[idx].z;
    }
    out
}

fn coord(p: Point3, axis: usize) -> f64 {
    match axis {
        0 => p.x,
        1 => p.y,
        _ => p.z,
    }
}

fn point_sum(terms: &[(f64, Point3)]) -> Point3 {
    let mut out = Point3::new(0.0, 0.0, 0.0);
    for &(w, p) in terms {
        out.x += w * p.x;
        out.y += w * p.y;
        out.z += w * p.z;
    }
    out
}

